import java.io.*;

public class Histo {
    static class Empty {}
    static class OneInt { int a; }
    static class Mixed { byte b; long l; int i; boolean f; }
    static class Ref { Object o; }
    static Object[] keep = new Object[5_000_000];

    public static void main(String[] args) throws Exception {
        int n = 1_000_000, k = 0;
        for (int i = 0; i < n; i++) keep[k++] = new Empty();
        for (int i = 0; i < n; i++) keep[k++] = new OneInt();
        for (int i = 0; i < n; i++) keep[k++] = new Mixed();
        for (int i = 0; i < n; i++) keep[k++] = new Ref();
        long pid = ProcessHandle.current().pid();
        Process p = new ProcessBuilder("jcmd", String.valueOf(pid), "GC.class_histogram")
            .redirectErrorStream(true).start();
        try (BufferedReader r = new BufferedReader(new InputStreamReader(p.getInputStream()))) {
            String line;
            while ((line = r.readLine()) != null)
                if (line.contains("Histo$") || line.contains("#instances"))
                    System.out.println(line);
        }
    }
}

import java.lang.reflect.Field;

public class Offsets {
    static class Mixed { byte b; long l; int i; boolean f; }
    static class Child extends Mixed { short s; }
    public static void main(String[] args) throws Exception {
        Field f = Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe");
        f.setAccessible(true);
        sun.misc.Unsafe u = (sun.misc.Unsafe) f.get(null);
        for (Class<?> c : new Class<?>[] {Mixed.class, Child.class})
            for (Field x : c.getDeclaredFields())
                System.out.println(c.getSimpleName() + "." + x.getName()
                    + " (" + x.getType() + ") offset " + u.objectFieldOffset(x));
        System.out.println("int[] base offset " + u.arrayBaseOffset(int[].class)
            + ", long[] base " + u.arrayBaseOffset(long[].class)
            + ", Object[] base " + u.arrayBaseOffset(Object[].class)
            + ", Object[] scale " + u.arrayIndexScale(Object[].class));
    }
}

import java.lang.management.*;

public class Escape {
    record Point(int x, int y) {}

    static int sumDistance(int a, int b) {
        Point p = new Point(a, b);          // never leaves this method
        return p.x() * p.x() + p.y() * p.y();
    }

    public static void main(String[] args) {
        long total = 0;
        for (int i = 0; i < 300_000_000; i++) total += sumDistance(i & 1023, 3);
        long gcs = 0;
        for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans())
            gcs += b.getCollectionCount();
        System.out.println("total=" + total + " gcCount=" + gcs);
    }
}

