        System.out.println(direct.capacity());
    }
}

import java.lang.ref.*;
import java.util.*;

public class Refs {
    static void gc() throws InterruptedException {
        System.gc();
        Thread.sleep(200);
    }

    public static void main(String[] args) throws Exception {
        Object strong = new Object();
        WeakReference<Object> weak = new WeakReference<>(new byte[1024]);
        SoftReference<Object> soft = new SoftReference<>(new byte[1024]);
        ReferenceQueue<Object> queue = new ReferenceQueue<>();
        Object victim = new Object();
        PhantomReference<Object> phantom = new PhantomReference<>(victim, queue);

        System.out.println("before gc: weak=" + (weak.get() != null)
            + " soft=" + (soft.get() != null) + " phantom.get()=" + phantom.get());
        victim = null;
        gc();
        System.out.println("after gc : weak=" + (weak.get() != null)
            + " soft=" + (soft.get() != null) + " strong=" + (strong != null));
        System.out.println("phantom enqueued: " + (queue.remove(1000) == phantom));

        WeakHashMap<Object, String> cache = new WeakHashMap<>();
        Object key = new Object();
        cache.put(key, "metadata");
        cache.put(new Object(), "orphan");
        gc();
        System.out.println("WeakHashMap size after gc: " + cache.size());
        key = null;
        gc();
        System.out.println("after dropping last key : " + cache.size());
    }
}

