import java.lang.ref.Cleaner;

public class CleanerDemo {
    static final Cleaner CLEANER = Cleaner.create();

    static class NativeHandle implements AutoCloseable {
        // The cleaning action must NOT reference the NativeHandle itself.
        private static class State implements Runnable {
            final String name;
            State(String name) { this.name = name; }
            public void run() { System.out.println("cleaned " + name); }
        }
        private final Cleaner.Cleanable cleanable;
        NativeHandle(String name) { cleanable = CLEANER.register(this, new State(name)); }
        @Override public void close() { cleanable.clean(); }
    }

    public static void main(String[] args) throws Exception {
        try (NativeHandle h = new NativeHandle("explicit")) {
            System.out.println("using " + h.getClass().getSimpleName());
        }
        new NativeHandle("forgotten");
        System.gc();
        Thread.sleep(300);
        System.out.println("done");
    }
}

