import java.lang.ref.WeakReference;

public class CycleReal {
    static class Node { Node other; byte[] pad = new byte[1000]; }

    public static void main(String[] args) throws Exception {
        Node x = new Node(), y = new Node();
        x.other = y; y.other = x;               // reference cycle
        WeakReference<Node> probe = new WeakReference<>(x);
        x = null; y = null;
        System.gc();
        Thread.sleep(100);
        System.out.println("cycle collected: " + (probe.get() == null));
    }
}

import java.util.*;

public class ToyGc {
    static class Node {
        final String name;
        final List<Node> refs = new ArrayList<>();
        boolean marked;
        Node(String name) { this.name = name; }
    }

    static void mark(Node n) {
        if (n == null || n.marked) return;      // the marked flag also stops cycles
        n.marked = true;
        for (Node r : n.refs) mark(r);
    }

    public static void main(String[] args) {
        Node a = new Node("A"), b = new Node("B"), c = new Node("C");
        Node d = new Node("D"), e = new Node("E"), f = new Node("F");
        a.refs.add(b);  b.refs.add(c);          // root -> A -> B -> C
        d.refs.add(e);  e.refs.add(d);          // D <-> E : a cycle nobody points to
        f.refs.add(c);                          // F -> C, but nobody points to F
        List<Node> heap = List.of(a, b, c, d, e, f);
        List<Node> roots = List.of(a);          // a local variable holds A

        for (Node r : roots) mark(r);           // phase 1: mark everything reachable
        List<Node> survivors = new ArrayList<>();
        for (Node n : heap) {                   // phase 2: sweep the rest
            if (n.marked) survivors.add(n);
            else System.out.println("sweep " + n.name);
        }
        System.out.println("survivors: " + survivors.stream().map(n -> n.name).toList());
    }
}

