import java.util.*;

public class Churn {
    public static void main(String[] args) {
        List<byte[]> retained = new ArrayList<>();
        long sum = 0;
        for (int i = 0; i < 3_000_000; i++) {
            byte[] tmp = new byte[1024];            // short-lived
            sum += tmp.length;
            if (i % 50 == 0) {                      // 2% of the data survives
                retained.add(new byte[1024]);
                if (retained.size() > 20_000) retained.subList(0, 10_000).clear();
            }
        }
        System.out.println(sum + " retained=" + retained.size());
    }
}

