import java.lang.management.*;
import java.util.*;

public class GcStats {
    public static void main(String[] args) {
        List<byte[]> retained = new ArrayList<>();
        long start = System.nanoTime();
        for (int i = 0; i < 4_000_000; i++) {
            byte[] tmp = new byte[1024];
            if (i % 8 == 0) {
                retained.add(new byte[1024]);
                if (retained.size() > 60_000) retained.subList(0, 30_000).clear();
            }
        }
        long ms = (System.nanoTime() - start) / 1_000_000;
        long count = 0, gcMs = 0;
        for (GarbageCollectorMXBean b : ManagementFactory.getGarbageCollectorMXBeans()) {
            count += b.getCollectionCount();
            gcMs += b.getCollectionTime();
        }
        System.out.println("maxHeap=" + Runtime.getRuntime().maxMemory() / (1 << 20)
            + "MB wall=" + ms + "ms collections=" + count + " gcTime=" + gcMs + "ms");
    }
}

import java.util.ArrayList;
import java.util.List;

public class Leak {
    static final List<byte[]> CACHE = new ArrayList<>();

    public static void main(String[] args) {
        Runtime rt = Runtime.getRuntime();
        try {
            for (int i = 1; ; i++) {
                CACHE.add(new byte[1024 * 1024]);          // 1 MB that is never removed
                if (i % 20 == 0) {
                    System.gc();
                    long used = (rt.totalMemory() - rt.freeMemory()) >> 20;
                    System.out.println("entries=" + i + " usedAfterGC=" + used + " MB");
                }
            }
        } catch (OutOfMemoryError e) {
            int n = CACHE.size();
            CACHE.clear();                                  // free memory so we can print
            System.out.println("Caught after " + n + " entries: " + e.getMessage());
        }
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TlLeak {
    static final ThreadLocal<byte[]> BUFFER = new ThreadLocal<>();

    static long usedMb() {
        System.gc();
        Runtime rt = Runtime.getRuntime();
        return (rt.totalMemory() - rt.freeMemory()) >> 20;
    }

    static void run(boolean remove) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(8);
        for (int i = 0; i < 8; i++) {
            pool.submit(() -> {
                try {
                    BUFFER.set(new byte[8 * 1024 * 1024]);
                    // handle a request using BUFFER.get()
                } finally {
                    if (remove) BUFFER.remove();
                }
            });
        }
        Thread.sleep(300);                 // tasks finished, threads stay alive in the pool
        System.out.println("remove=" + remove + "  used after GC: " + usedMb() + " MB");
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
    }

    public static void main(String[] args) throws Exception {
        run(false);
        System.out.println("after pool shutdown: " + usedMb() + " MB");
        run(true);
    }
}

