import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

public class MetaLeak {
    public static void main(String[] args) {
        List<Object> keep = new ArrayList<>();
        try {
            for (int i = 0; ; i++) {
                ClassLoader loader = new ClassLoader(null) { };   // a fresh loader each time
                keep.add(Proxy.newProxyInstance(loader, new Class<?>[] {Runnable.class},
                        (proxy, method, a) -> null));            // defines a new proxy class
                if (i % 2000 == 0) System.out.println("loaders created: " + i);
            }
        } catch (OutOfMemoryError e) {
            int n = keep.size();
            keep.clear();
            System.out.println("Caught after " + n + " loaders: " + e.getMessage());
        }
    }
}

public class Warm {
    static int score(int x) { return (x * 31 + 7) % 1000; }

    static long batch(int n) {
        long sum = 0;
        for (int i = 0; i < n; i++) sum += score(i);
        return sum;
    }

    public static void main(String[] args) {
        for (int round = 1; round <= 8; round++) {
            long t0 = System.nanoTime();
            long r = batch(2_000_000);
            long micros = (System.nanoTime() - t0) / 1000;
            System.out.println("round " + round + ": " + micros + " us (result " + r + ")");
        }
    }
}

public class Deopt {
    interface Shape { double area(); }
    record Square(double s) implements Shape { public double area() { return s * s; } }
    record Circle(double r) implements Shape { public double area() { return 3.14159 * r * r; } }

    static double total(Shape[] shapes) {
        double t = 0;
        for (Shape s : shapes) t += s.area();
        return t;
    }

    public static void main(String[] args) {
        Shape[] squares = new Shape[1000];
        for (int i = 0; i < squares.length; i++) squares[i] = new Square(i);
        double sink = 0;
        for (int i = 0; i < 20_000; i++) sink += total(squares);
        System.out.println("phase 1 done (only Square seen)");
        Shape[] mixed = new Shape[1000];
        for (int i = 0; i < mixed.length; i++) {
            mixed[i] = (i % 2 == 0) ? new Square(i) : new Circle(i);
        }
        for (int i = 0; i < 20_000; i++) sink += total(mixed);
        System.out.println("phase 2 done (Square and Circle)");
        System.out.println(sink > 0);
    }
}

public class Bad {
    public static void main(String[] args) {
        for (int round = 0; round < 5; round++) {
            long t0 = System.nanoTime();
            for (int i = 0; i < 100_000_000; i++) {
                Math.sqrt(i);                 // result unused
            }
            System.out.println("loop took " + (System.nanoTime() - t0) / 1_000_000 + " ms");
        }
    }
}

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.concurrent.TimeUnit;

@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 5, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(2)
@State(Scope.Thread)
public class SqrtBenchmark {
    double x = 12345.678;                 // a field, so it is not a compile-time constant

    @Benchmark
    public void sqrt(Blackhole bh) {
        bh.consume(Math.sqrt(x));
    }
}
